// Deterministic phone normalisation to E.164 + workflow constants.
// Runs before anything else. No LLM involved.
function toE164(raw) {
  let d = String(raw || '').replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);
  if (d.startsWith('0')) d = '20' + d.slice(1);   // local Egyptian format
  return '+' + d;
}

const jid = $json.body?.data?.key?.remoteJid || '';
const waNumber = String(jid).split('@')[0];
const e164 = toE164(waNumber);

return [{
  json: {
    ...$json,
    wa_number: waNumber,
    wa_e164: e164,
    wa_last9: e164.replace(/\D/g, '').slice(-9),

    // ---- CONFIG (edit here only) ----
    // VERIFIED IN ODOO: res.partner.category id 6 = "Distributor" (child tag 35 = "Saudi partner").
    // res.partner has NO x_is_distributor field and NO mobile field in Odoo 19.
    dist_tag_id: 6,
    support_partner_id: 671           // Mai Magdy - res.partner id -> res.users id resolved at runtime (412)
  }
}];

// STEP 1: collect only ACTIVE distributor-associated contacts whose normalized phone exactly matches WhatsApp.
// Do not mark the number ambiguous yet; the upstream Odoo domain already excludes contacts outside Distributor commercial companies.
const cfg = $('Config').first().json;
const inp = $('Prepare Input').first().json;
const target = cfg.wa_e164;

function toE164(raw) {
  let d = String(raw || '').replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);
  if (d.startsWith('0')) d = '20' + d.slice(1);
  return '+' + d;
}
const m2o = (v, i) => (Array.isArray(v) ? v[i] : (i === 0 ? (v || 0) : ''));
const seen = new Set();
const candidates = [];

for (const row of $input.all().map(i => i.json)) {
  if (!row || !row.id || row.active === false || seen.has(Number(row.id))) continue;
  const numbers = [row.phone_sanitized, row.phone].map(toE164).filter(Boolean);
  if (!target || !numbers.includes(target)) continue;
  seen.add(Number(row.id));
  const companyId = Number(m2o(row.commercial_partner_id, 0)) || Number(row.id);
  const companyName = String(m2o(row.commercial_partner_id, 1) || row.name || '');
  candidates.push({
    id: Number(row.id),
    name: String(row.name || ''),
    commercial_partner_id: companyId,
    company_name: companyName,
    contact_pricelist_id: Number(m2o(row.property_product_pricelist, 0) || 0),
    salesperson: String(m2o(row.user_id, 1) || '')
  });
}

const companyMap = new Map();
for (const c of candidates) if (!companyMap.has(c.commercial_partner_id)) companyMap.set(c.commercial_partner_id, c.company_name);

return [{ json: {
  Text: inp.Text,
  wa_number: inp.wa_number,
  wa_e164: target,
  wa_last9: inp.wa_last9,
  phone_candidates: candidates,
  candidate_company_ids: [...companyMap.keys()],
  all_candidate_company_names: [...companyMap.values()].filter(Boolean)
}}];

// STEP 3: ignore non-distributor duplicates and resolve only eligible distributor companies.
const m = $('Match Phone Candidates').first().json;
const candidates = Array.isArray(m.phone_candidates) ? m.phone_candidates : [];
const m2o = (v, i) => (Array.isArray(v) ? v[i] : (i === 0 ? (v || 0) : ''));
const norm = (s) => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();

const candidateCompanyIds = new Set(candidates.map(c => Number(c.commercial_partner_id || 0)).filter(id => id > 0));
const distributorCompanies = $input.all()
  .map(i => i.json)
  .filter(c => c && Number(c.id) > 0 && c.active !== false && candidateCompanyIds.has(Number(c.id)));

// One company may arrive more than once; keep one row per commercial company.
const eligibleMap = new Map();
for (const company of distributorCompanies) if (!eligibleMap.has(Number(company.id))) eligibleMap.set(Number(company.id), company);
const eligibleCompanies = [...eligibleMap.values()];

let selectedCompany = null;
if (eligibleCompanies.length === 1) {
  selectedCompany = eligibleCompanies[0];
} else if (eligibleCompanies.length > 1) {
  // Resolve only when the message explicitly identifies exactly one eligible distributor company.
  const message = norm(m.Text);
  const named = eligibleCompanies.filter(c => {
    const name = norm(c.name);
    return name && (message === name || message.includes(name));
  });
  if (named.length === 1) selectedCompany = named[0];
}

const ambiguous = eligibleCompanies.length > 1 && !selectedCompany;
const companyId = selectedCompany ? Number(selectedCompany.id) : 0;
const companyCandidates = companyId ? candidates.filter(c => Number(c.commercial_partner_id) === companyId) : [];
// Prefer the contact record itself; duplicates under the same distributor company are allowed.
const selectedContact = companyCandidates.find(c => Number(c.id) !== companyId) || companyCandidates[0] || null;
const verified = !ambiguous && !!selectedCompany && !!selectedContact;

const companyPricelistId = Number(m2o(selectedCompany && selectedCompany.property_product_pricelist, 0) || 0);
const contactPricelistId = verified ? Number(selectedContact.contact_pricelist_id || 0) : 0;
const pricelistId = verified ? (contactPricelistId || companyPricelistId || 1) : 0;
const totalOverdue = verified ? Number(selectedCompany.total_overdue || 0) : 0;
const trust = verified ? String(selectedCompany.trust || '') : '';

return [{ json: {
  Text: m.Text,
  wa_number: m.wa_number,
  wa_e164: m.wa_e164,
  wa_last9: m.wa_last9,
  is_verified: verified,
  ambiguous_number: ambiguous,
  candidate_company_names: eligibleCompanies.map(c => String(c.name || '')).filter(Boolean),
  partner_id: verified ? Number(selectedContact.id) : 0,
  commercial_partner_id: verified ? companyId : 0,
  partner_name: verified ? String(selectedContact.name || '') : '',
  company_name: verified ? String(selectedCompany.name || '') : '',
  pricelist_id: pricelistId,
  pricelist_source: verified ? (contactPricelistId ? 'contact' : (companyPricelistId ? 'company' : 'default_1')) : 'none',
  salesperson: verified ? (String(selectedContact.salesperson || '') || String(m2o(selectedCompany.user_id, 1) || '')) : '',
  total_due: verified ? Number(selectedCompany.total_due || 0) : 0,
  total_overdue: totalOverdue,
  credit_limit: verified ? Number(selectedCompany.credit_limit || 0) : 0,
  account_trust: trust,
  account_warning: verified ? String(selectedCompany.sale_warn_msg || '') : '',
  account_frozen: verified && trust === 'bad',
  has_overdue: verified && totalOverdue > 0,
  matching_contact_count: candidates.length,
  eligible_distributor_company_count: eligibleCompanies.length
}}];

// Deterministic verified-distributor context. No lead/onboarding path exists in v7.
const d = $('Resolve Distributor').first().json;
const pid = Number(d.pricelist_id || 0);
const canQuote = d.is_verified === true && d.ambiguous_number !== true && Number(d.partner_id || 0) > 0 && pid > 0;
return [{ json: { ...d, can_quote_price: canQuote } }];

// Deterministic parser, fallback + hard downgrades. Nothing here trusts the LLM.
const ctx = $('Build Agent Context').first().json;
const raw = $json.output;
let text = typeof raw === 'string' ? raw : JSON.stringify(raw ?? '');
let d = null;

if (raw && typeof raw === 'object') {
  d = raw;
} else {
  const cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();
  try { d = JSON.parse(cleaned); } catch (e) {
    const m = cleaned.match(/\{[\s\S]*\}/);
    if (m) { try { d = JSON.parse(m[0]); } catch (e2) { d = null; } }
  }
}
if (!d || typeof d !== 'object') d = { action: 'reply_text', reply: text.replace(/```/g, '').trim() };

const ALLOWED = ['reply_text', 'send_product_pdf', 'send_quotation_pdf'];
let action = ALLOWED.includes(String(d.action)) ? String(d.action) : 'reply_text';

let reply = String(d.reply || '').trim();
const attachment_id = Number(d.attachment_id || 0);
const product_id = Number(d.product_id || 0);
const product_template_id = Number(d.product_template_id || 0);
const quotation_id = Number(d.quotation_id || 0);
const quotation_name = String(d.quotation_name || '');

// ---- HARD GUARDS (deterministic, not prompt-based) ----
if (action === 'send_product_pdf') {
  const ok = ctx.is_verified === true && attachment_id > 0 && product_id > 0;
  if (!ok) {
    action = 'reply_text';
    reply = reply || 'معلش، مش قادر أبعت الملف دلوقتي. هرفع طلبك للمسؤول.';
  }
}
if (action === 'send_quotation_pdf') {
  const ok = ctx.is_verified === true && ctx.ambiguous_number !== true && Number(ctx.commercial_partner_id || 0) > 0 && quotation_id > 0;
  if (!ok) {
    action = 'reply_text';
    reply = 'تعذر تجهيز ملف عرض السعر بأمان. من فضلك حاول مرة تانية أو تواصل مع مسؤول حسابك.';
  }
}
if (action === 'create_distributor_lead') {
  // only for unknown numbers with no existing lead
  if (ctx.is_verified === true || ctx.existing_lead === true) {
    action = 'reply_text';
    if (ctx.existing_lead === true && ctx.is_verified !== true) {
      reply = reply || 'طلب الانضمام بتاعك مسجل عندنا بالفعل، وهيتم التواصل معاك قريب.';
    }
  }
}
if (ctx.ambiguous_number === true) {
  // number registered under more than one company: ask, never claim anything was logged
  action = 'reply_text';
  const names = Array.isArray(ctx.candidate_company_names) ? ctx.candidate_company_names.filter(Boolean) : [];
  reply = names.length ? ('الرقم مسجل على أكتر من شركة: ' + names.join('، ') + '. اكتب اسم الشركة المطلوبة فقط.') : 'الرقم مسجل على أكتر من شركة. اكتب اسم الشركة المطلوبة فقط.';
}
const menuChoice = Number($('Map Menu Selection').first().json.selected_service_number || 0);
const genericReply = /(?:ممكن|يرجى|من فضلك)?\s*(?:توضح|وضّح)\s*(?:طلبك|الطلب)/i.test(reply);
if (menuChoice > 0 && genericReply) {
  const starts = {
    1: 'ثواني أراجع طلباتك الحالية المسجلة على Odoo.',
    2: 'ثواني أراجع الأصناف المتاحة للتسليم على طلبات حسابك.',
    3: 'ثواني أراجع المبلغ المطلوب قبل الاستلام على حسابك.',
    4: 'ثواني أراجع ملخص حسابك والمدفوعات المسجلة.',
    5: 'ابعت اسم أو كود المنتج المطلوب.',
    6: 'ما اسم المشروع الجديد؟',
    7: 'ثواني أراجع المشروعات المسجلة على حسابك.',
    8: 'ابعت اسم أو كود المنتج والكمية المطلوبة.',
    9: 'ما اسم المنتج وما المشكلة الفنية؟',
    10: 'ما اسم المنتج أو السيريال ووصف العطل؟',
    11: 'ابعت رقم الطلب أو الفاتورة وسبب المرتجع.',
    12: 'هسجل طلب تواصل مع مسؤول حسابك.'
  };
  reply = starts[menuChoice] || reply;
}
if (!reply) reply = 'تمام، ممكن توضح طلبك أكتر؟';

return [{
  json: {
    action,
    reply,
    is_verified: ctx.is_verified === true,
    verified_partner_id: Number(ctx.partner_id || 0),
    existing_lead: ctx.existing_lead === true,
    product_id,
    product_template_id,
    attachment_id,
    quotation_id,
    quotation_name,
    file_name: String(d.file_name || 'datasheet.pdf'),
    mime_type: 'application/pdf',
    needs_approval: Boolean(d.needs_approval),
    lead_title: String(d.lead_title || ('طلب انضمام موزع - ' + (d.lead_company_name || ctx.wa_number))),
    lead_company_name: String(d.lead_company_name || ''),
    lead_contact_name: String(d.lead_contact_name || ''),
    lead_email: String(d.lead_email || ''),
    lead_address: String(d.lead_address || ''),
    lead_summary: String(d.lead_summary || reply),
    support_summary: String(d.support_summary || 'طلب موزع يحتاج متابعة'),
    support_note: String(d.support_note || reply)
  }
}];

// Deterministic PDF authorisation. Never trust product_template_id supplied by the AI.
const p = $('Parse Agent Response').first().json;
const product = $('Odoo Resolve Actual Product Template').first().json || {};
const a = $json || {};
const m2oId = (value) => Array.isArray(value) ? Number(value[0] || 0) : Number(value || 0);

const requestedProductId = Number(p.product_id || 0);
const actualProductId = Number(product.id || 0);
const actualTemplateId = m2oId(product.product_tmpl_id);
const productResolved = requestedProductId > 0 && actualProductId === requestedProductId && actualTemplateId > 0;

const linkOk = productResolved && (
  (a.res_model === 'product.product' && Number(a.res_id) === actualProductId) ||
  (a.res_model === 'product.template' && Number(a.res_id) === actualTemplateId)
);

const allowed =
  p.is_verified === true &&
  Number(p.attachment_id) > 0 &&
  Number(a.id) === Number(p.attachment_id) &&
  linkOk &&
  a.mimetype === 'application/pdf' &&
  !!a.datas;

return [{
  json: {
    allowed,
    reason: allowed ? 'ok' : 'blocked: attachment is not linked to the resolved product/template',
    requested_product_id: requestedProductId,
    resolved_product_id: actualProductId,
    resolved_product_template_id: actualTemplateId,
    attachment_res_model: String(a.res_model || ''),
    attachment_res_id: Number(a.res_id || 0),
    media: allowed ? String(a.datas).replace(/\s/g, '') : '',
    file_name: String(a.name || p.file_name || 'datasheet.pdf'),
    reply: p.reply
  }
}];

