const j = $input.first().json;
const raw = String(j.Text || '').trim();
const n = /^(?:0?[1-9]|1[0-2])$/.test(raw) ? Number(raw) : 0;
const cid = Number(j.commercial_partner_id || 0);
const services = {
  1: ['متابعة طلب حالي', 'search_records', 'نفّذ فورًا على sale.order بفلتر partner_id child_of ' + cid + ' واعرض رقم الطلب والحالة والتاريخ والإجمالي وحالة الفاتورة والتسليم.'],
  2: ['الأصناف المتاحة للتسليم', 'search_records', 'نفّذ فورًا على stock.move بفلتر picking_id.partner_id child_of ' + cid + ' والحالات assigned/confirmed/waiting، واعرض المنتج والكمية المتاحة وحالة التسليم فقط.'],
  3: ['المبلغ المطلوب قبل الاستلام', 'search_records', 'نفّذ فورًا على account.move بفلتر partner_id child_of ' + cid + ' وmove_type=out_invoice وstate=posted وamount_residual>0، واعرض الإجمالي المتبقي وتواريخ الاستحقاق.'],
  4: ['كشف الحساب والمدفوعات', 'search_records', 'اقرأ account.move ثم account.payment للحساب child_of ' + cid + '، واعرض ملخصًا مختصرًا للفواتير والمدفوع والمتبقي فقط.'],
  5: ['أسعار المنتجات والخصومات', 'search_products', 'اطلب اسم أو كود منتج واحد فقط، ثم ابحث عنه واعرض سعر البيع الحالي الموجود في Odoo دون تكلفة أو هامش أو تخمين.'],
  6: ['تسجيل مشروع جديد', 'create_activity', 'اجمع اسم المشروع والموقع والمنتجات المتوقعة والموعد، لخّص واطلب تأكيدًا، ثم أنشئ Activity على res.partner رقم ' + cid + '.'],
  7: ['متابعة مشروع مسجل', 'search_records', 'نفّذ فورًا على project.project بفلتر partner_id child_of ' + cid + ' واعرض الاسم والحالة والمسؤول والتقدم فقط.'],
  8: ['طلب عرض سعر جديد', 'create_activity', 'اجمع المنتج والكمية والمشروع والموعد، لخّص واطلب تأكيدًا، ثم أنشئ Activity لطلب عرض سعر على res.partner رقم ' + cid + '.'],
  9: ['الدعم الفني', 'create_activity', 'اجمع اسم/كود المنتج ووصف المشكلة، لخّص واطلب تأكيدًا، ثم أنشئ Activity دعم فني على res.partner رقم ' + cid + '.'],
  10: ['الضمان والصيانة', 'create_activity', 'اجمع المنتج والسيريال ورقم الفاتورة والعطل، لخّص واطلب تأكيدًا، ثم أنشئ Activity ضمان/صيانة على res.partner رقم ' + cid + '.'],
  11: ['المرتجعات والاستبدال', 'create_activity', 'اجمع رقم الطلب/الفاتورة والمنتج والكمية والسبب، لخّص واطلب تأكيدًا، ثم أنشئ Activity مرتجع/استبدال على res.partner رقم ' + cid + '.'],
  12: ['التحدث مع مسؤول الحساب', 'create_activity', 'أنشئ فورًا Activity طلب تواصل مع مسؤول الحساب على res.partner رقم ' + cid + '.'],
};
const s = services[n] || ['', '', ''];
const forcedText = n ? ('[VERIFIED MENU ACTION] option=' + n + '; service=' + s[0] + '; required_mcp_tool=' + s[1] + '; instruction=' + s[2]) : raw;
return [{ json: {
  ...j,
  user_original_text: raw,
  Text: forcedText,
  selected_service_number: n,
  selected_service: s[0],
  required_mcp_tool: s[1],
  service_instruction: s[2]
}}];

