// Authorize the quotation and build its portal PDF URL from the trusted Odoo record.
const p = $('Parse Agent Response').first().json;
const ctx = $('Build Agent Context').first().json;
const q = $json || {};
const m2o = v => Array.isArray(v) ? Number(v[0] || 0) : Number(v || 0);
const quoteId = Number(q.id || 0);
const partnerId = m2o(q.partner_id);
const state = String(q.state || '');
const token = String(q.access_token || '');
const ownershipOk = ctx.is_verified === true && ctx.ambiguous_number !== true && Number(p.quotation_id || 0) === quoteId && quoteId > 0 && partnerId === Number(ctx.commercial_partner_id || 0) && ['draft','sent'].includes(state);
const allowed = ownershipOk && token.length >= 16;
const currency = Array.isArray(q.currency_id) ? String(q.currency_id[1] || '') : '';
const pdfUrl = allowed ? ('https://thelvx.odoo.com/my/orders/' + quoteId + '?access_token=' + encodeURIComponent(token) + '&report_type=pdf&download=true') : '';
return [{json:{allowed,quotation_id:quoteId,quotation_name:String(q.name || p.quotation_name || ('Quotation-' + quoteId)),amount_total:Number(q.amount_total || 0),currency,pdf_url:pdfUrl,error_reply:allowed ? '' : (ownershipOk ? 'تعذر تجهيز رابط PDF لعرض السعر. حاول مرة أخرى أو تواصل مع مسؤول حسابك.' : 'تم منع إرسال الملف لأن عرض السعر غير مرتبط بحساب الموزع المتحقق منه.')}}];
